SELECT u.id, u.username, u.password, u.nickname, u.avatar, u.email, u.phone, u.target_school, u.target_score, u.exam_year, u.prep_stage, u.status, u.created_at, u.updated_at, r.role_code FROM sys_user u LEFT JOIN sys_user_role ur ON u.id = ur.user_id LEFT JOIN sys_role r ON ur.role_id = r.id
AND (u.username LIKE CONCAT('%', #{query.keyword}, '%') OR u.nickname LIKE CONCAT('%', #{query.keyword}, '%') OR u.target_school LIKE CONCAT('%', #{query.keyword}, '%'))
AND u.status = #{query.status}
AND r.role_code = #{query.roleCode}
ORDER BY u.id ASC LIMIT #{offset}, #{limit}

SELECT COUNT(DISTINCT u.id) FROM sys_user u LEFT JOIN sys_user_role ur ON u.id = ur.user_id LEFT JOIN sys_role r ON ur.role_id = r.id
AND (u.username LIKE CONCAT('%', #{query.keyword}, '%') OR u.nickname LIKE CONCAT('%', #{query.keyword}, '%') OR u.target_school LIKE CONCAT('%', #{query.keyword}, '%'))
AND u.status = #{query.status}
AND r.role_code = #{query.roleCode}

