UPDATE sys_user
nickname = #{nickname}, email = #{email}, phone = #{phone}, target_school = #{targetSchool}, target_score = #{targetScore}, exam_year = #{examYear}, prep_stage = #{prepStage}, status = #{status},
WHERE id = #{id}

UPDATE sys_user
SET status = #{status}
WHERE id = #{id}

UPDATE sys_user
SET password = #{password}
WHERE id = #{id}
